// CSV field quoting utility
export function quoteField(field: string | number): string {
  const str = String(field);
  if (str.includes('"')) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  if (str.includes(",") || str.includes("\n")) {
    return `"${str}"`;
  }
  return str;
}

// Format number to 2 decimal places for CSV export
export function formatNumberForCSV(value: number): number {
  return Math.round(value * 100) / 100;
}

// Format percentage with 1 decimal place and % symbol
export function formatPercentageForCSV(value: number): string {
  return `${(Math.round(value * 10) / 10).toFixed(1)}%`;
}

// CSV generation function for chart data
export function chartDataToCSV(
  data: { [key: string]: string | number }[],
  datasets: { label: string }[]
): string {
  const header = ["Name", ...datasets.map((ds) => ds.label)]
    .map(quoteField)
    .join(",");

  const rows = data.map((entry) => {
    const row = [
      entry.name,
      ...datasets.map((ds) => {
        const value = entry[ds.label];
        if (typeof value === 'number') {
          // Check if this is a percentage column
          if (ds.label.toLowerCase().includes('percentage') || ds.label.toLowerCase().includes('percent')) {
            return formatPercentageForCSV(value);
          }
          return formatNumberForCSV(value);
        }
        return value || 0;
      }),
    ].map(quoteField);
    return row.join(",");
  });

  return [header, ...rows].join("\r\n");
}

// ─── Active filter cache ───────────────────────────────────────────────────────
// TopMenu writes here on every filter change via setActiveFiltersMeta().
// downloadCSV reads it to append a Filters section without touching any chart component.

interface FilterOptionMeta {
  value: string;
  label: string;
}

interface DimensionMeta {
  label: string;
  options: FilterOptionMeta[];
}

let _activeFilters: { field: string; value: string | number }[] = [];
let _dimensionMeta: Record<string, DimensionMeta> = {};

export function setActiveFiltersMeta(
  filters: { field: string; value: string | number }[],
  dimensionMeta: Record<string, DimensionMeta>
): void {
  _activeFilters = filters;
  _dimensionMeta = dimensionMeta;
}

function buildFiltersSection(): string {
  // Group raw filters by field, skip the sentinel used for 0-selection
  const byField: Record<string, string[]> = {};
  _activeFilters.forEach(f => {
    if (f.value === '__no_match__') {
      // 0 options selected for this dimension — still report it
      if (!byField[f.field]) byField[f.field] = [];
    } else {
      if (!byField[f.field]) byField[f.field] = [];
      byField[f.field].push(String(f.value));
    }
  });

  const fields = Object.keys(byField);
  if (fields.length === 0) {
    return [
      '',
      'Active Filters',
      'Status',
      'No filters applied — showing all respondents',
    ].join('\r\n');
  }

  const rows: string[] = ['', 'Active Filters', 'Dimension,Selected Options'];
  fields.forEach(field => {
    const meta = _dimensionMeta[field];
    const dimLabel = meta?.label ?? field;
    const selectedValues = byField[field];

    if (selectedValues.length === 0) {
      rows.push(`${quoteField(dimLabel)},${quoteField('None selected')}`);
      return;
    }

    const optionLabels = selectedValues.map(v => {
      const opt = meta?.options.find(o => o.value === v);
      return opt ? opt.label : v;
    });

    rows.push(`${quoteField(dimLabel)},${quoteField(optionLabels.join('; '))}`);
  });

  return rows.join('\r\n');
}

// Download handler — automatically appends the active filters section
export function downloadCSV(csv: string, filename: string): void {
  const fullContent = csv + '\r\n' + buildFiltersSection();
  const blob = new Blob([fullContent], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
